  69     subscribeToUserProfile(userId: string, firestore: Firestore, callback: (user: UserProfile | null) => void) {
  70         // Pass firestore instance from outside to avoid mixed library versions
  71         if (typeof window === 'undefined' || !firestore) {
  72             return () => {}; 
