  79                 callback({ id: snapshot.id, ...snapshot.data() } as UserProfile);
  80             } else {
  81                 callback(null);
  82             }
  83         }, (error: any) => {
  84             console.error("Error listening to user profile:", error);
  85             callback(null);
  86         });
  87 
  88         return unsubscribe;
  89     }
