  13         const markdown = this.generateMarkdownFromContent(content);
  14         
  15         // Extract footnotes from full project content
  16         const fullMarkdown = project.fullMarkdownContent || '';
  17         const footnoteRegex = /^\[\^.+?\]:.+$/gm;
  18         const footnoteDefinitions = fullMarkdown.match(footnoteRegex);
  19 
  20         let finalMarkdown = markdown;
  21         if (footnoteDefinitions) {
  22             finalMarkdown += '\n\n' + footnoteDefinitions.join('\n');
  23         }
  24 
  25         const result = await convertMarkdownToPptx(finalMarkdown, project.name, {
  26             styles: options.styles,
  27             isRtl: options.isRtl,
  28             includeToc: options.includeToc,
  29         });
  30 
  31         return result instanceof Blob ? result : new Blob([result as any], { 
  32             type: 'application/vnd.openxmlformats-officedocument.presentationml.presentation' 
  33         });
  34     }
