  36     private generateMarkdownFromContent(content: ProjectContent): string {
  37         return content.map(item => {
  38             if (item instanceof Chapter) {
  39                 const chapterContent = `# ${item.title}`;
  40                 const sectionsContent = item.sections.map(section => 
  41                     `## ${section.title}\n\n${section.content || ''}`
  42                 ).join('\n\n');
  43                 return `${chapterContent}\n\n${sectionsContent}`;
  44             } else {
  45                 return `# ${item.title}\n\n${item.content || ''}`;
