  29 
  30 export async function convertMarkdownToPptx(
  31     markdown: string,
  32     fileName: string,
  33     options: PptxConversionOptions = {},
  34 ): Promise<Buffer | Blob> {
  35     const pptx = new PptxGenJS();
  36     const { styles = templates.modern.styles, isRtl = false, fonts = {}, includeToc = false } = options;
  37 
  38     pptx.rtlMode = isRtl;
  39     pptx.layout = 'LAYOUT_16x9';
  40     const COVER_MASTER = 'COVER_MASTER';
  41     const CONTENT_MASTER = 'CONTENT_MASTER';
  42 
  43     const titleStyle = { ...styles.title };
  44     const defaultFont = isRtl ? fonts.rtl : fonts.default;
  45     if (defaultFont) titleStyle.fontFace = defaultFont;
  46 
  47     const coverTitleStyle = { ...titleStyle, align: 'center', valign: 'middle', fontSize: 44 };
  48     const contentTitleStyle = { ...titleStyle, align: isRtl ? 'right' : styles.title.align };
  49 
  50     // Define Cover Slide Master
  51     pptx.defineSlideMaster({
  52         title: COVER_MASTER,
  53         background: styles.background,
  54         objects: [
  55             {
  56                 placeholder: { // @ts-ignore
  57                     options: { name: 'title', type: 'title', x: 0.5, y: 0, w: '90%', h: '100%', ...coverTitleStyle, rtlMode: isRtl }, // @ts-ignore
  58                 },
  59             },
  60         ],
  61     });
  62 
  63     // Define Content Slide Master
  64     pptx.defineSlideMaster({
  65         title: CONTENT_MASTER,
  66         background: styles.background,
  67         objects: [{
  68             placeholder: { options: { name: 'title', type: 'title', x: layout.CONTENT_X, y: layout.TITLE_Y, w: layout.CONTENT_WIDTH, h: layout.TITLE_H, margin: 0, ...contentTitleStyle } },
  69         },],
  70     });
  71 
  72     pptx.layout = 'LAYOUT_16x9';
  73     pptx.author = options.author || 'Arkan';
