  80     let slidesContent = splitAstIntoSlides(ast);
  81 
  82     if (includeToc && slidesContent.length > 0) {
  83         const tocItems: ListItem[] = [];
  84         // Generate TOC from all slides that have a title.
  85         for (const slideAst of slidesContent) {
