  14 // File processing utilities
  15 async function extractTextFromFile(file: File): Promise<string> {
  16   const filename = file.name.toLowerCase();
  17   
  18   // PDF files
  19   if (filename.endsWith('.pdf')) {
  20     return await extractTextFromPDF(file);
  21   }
  22   
  23   // DOCX files
  24   if (filename.endsWith('.docx')) {
  25     return await extractTextFromDOCX(file);
  26   }
  27   
  28   // Text/Markdown files
  29   if (filename.endsWith('.txt') || filename.endsWith('.md')) {
  30     return await file.text();
  31   }
  32   
  33   throw new Error('Unsupported file type. Please upload PDF, DOCX, TXT, or MD files.');
  34 }
  35 
  36 async function extractTextFromPDF(file: File): Promise<string> {
  37   try {
  38     const pdfParse = require('pdf-parse');
  39     const options = { max: 0 };
  40     const buffer = await file.arrayBuffer();
  41     const data = await pdfParse(Buffer.from(buffer), options);
  42     
  43     if (!data.text || data.text.trim().length === 0) {
  44       throw new Error('No text content found in PDF');
  45     }
  46     return data.text;
  47   } catch (error) {
  48     console.error('PDF extraction error:', error);
  49     throw new Error('Failed to extract text from PDF.');
  50   }
  51 }
  52 
  53 async function extractTextFromDOCX(file: File): Promise<string> {
  54   try {
  55     const mammoth = require('mammoth');
  56     const buffer = await file.arrayBuffer();
  57     const result = await mammoth.extractRawText({ buffer: Buffer.from(buffer) });
  58     return result.value;
  59   } catch (error) {
  60     console.error('DOCX extraction error:', error);
  61     throw new Error('Failed to extract text from DOCX.');
  62   }
  63 }
