  17           'Explain vector databases',
  18           'What is semantic search?',
  19           'Tell me about React',
  20         ];
  21 
  22         const scenarios = [
  23           { name: 'Without Cache', useCache: false, rerank: false },
  24           { name: 'With Cache', useCache: true, rerank: false },
  25           { name: 'With Cache + Re-ranking', useCache: true, rerank: true },
  26         ];
  27 
  28         const totalSteps = scenarios.length * testQueries.length;
  29         let currentStep = 0;
  30 
  31         for (const scenario of scenarios) {
  32           const times: number[] = [];
  33           let cacheHits = 0;
  34 
  35           // Run queries for this scenario
  36           for (const query of testQueries) {
  37             const startTime = Date.now();
  38             
