  25 /**
  26  * Generic LRU Cache implementation
  27  */
  28 class LRUCache<T> {
  29   private cache: Map<string, CacheEntry<T>>;
  30   private maxSize: number;
  31   private ttl: number;
  32   private stats: { hits: number; misses: number; evictions: number };
  33 
  34   constructor(maxSize: number = 1000, ttl: number = 3600000) {
  35     this.cache = new Map();
  36     this.maxSize = maxSize;
  37     this.ttl = ttl; // milliseconds
  38     this.stats = { hits: 0, misses: 0, evictions: 0 };
  39   }
  40 
  41   /**
  42    * Get value from cache
  43    */
  44   get(key: string): T | null {
  45     const entry = this.cache.get(key);
  46 
  47     if (!entry) {
  48       this.stats.misses++;
  49       return null;
  50     }
  51 
  52     // Check if expired
  53     if (Date.now() - entry.timestamp > this.ttl) {
  54       this.cache.delete(key);
  55       this.stats.misses++;
  56       return null;
  57     }
  58 
  59     // Update stats and move to end (LRU)
  60     this.stats.hits++;
  61     entry.hits++;
  62     
  63     // Move to end (refresh)
  64     this.cache.delete(key);
  65     this.cache.set(key, entry);
  66 
  67     return entry.value;
  68   }
  69 
  70   /**
  71    * Set value in cache
  72    */
  73   set(key: string, value: T): void {
  74     // Remove oldest if at capacity
  75     if (this.cache.size >= this.maxSize && !this.cache.has(key)) {
  76       const firstKey = this.cache.keys().next().value as string | undefined;
  77       if (firstKey) this.cache.delete(firstKey);
  78       this.stats.evictions++;
  79     }
  80 
  81     // Add/update entry
  82     this.cache.set(key, {
  83       value,
  84       timestamp: Date.now(),
  85       hits: 0,
  86     });
  87   }
  88 
  89   /**
  90    * Check if key exists and is valid
  91    */
  92   has(key: string): boolean {
  93     return this.get(key) !== null;
  94   }
  95 
  96   /**
  97    * Clear all cache
  98    */
  99   clear(): void {
 100     this.cache.clear();
