 155   /**
 156    * Generate cache key from text
 157    */
 158   private getCacheKey(text: string): string {
 159     // Simple hash for cache key
 160     let hash = 0;
 161     for (let i = 0; i < text.length; i++) {
 162       const char = text.charCodeAt(i);
 163       hash = ((hash << 5) - hash) + char;
 164       hash = hash & hash; // Convert to 32-bit integer
 165     }
 166     return `emb_${hash}_${text.length}`;
 167   }
