 283    */
 284   private startAutoPrune(): void {
 285     if (this.pruneInterval) {
 286       clearInterval(this.pruneInterval);
 287     }
 288 
 289     this.pruneInterval = setInterval(() => {
 290       const embPruned = this.embeddingCache.prune();
 291       const searchPruned = this.searchCache['cache'].prune();
 292       
 293       if (embPruned > 0 || searchPruned > 0) {
 294         console.log(`[Cache] Pruned ${embPruned} embeddings, ${searchPruned} searches`);
 295       }
 296     }, 300000); // 5 minutes
 297   }
 298 
 299   /**
 300    * Stop auto-pruning
 301    */
 302   stopAutoPrune(): void {
 303     if (this.pruneInterval) {
 304       clearInterval(this.pruneInterval);
 305       this.pruneInterval = null;
 306     }
 307   }
 308 
