  12     async indexDocument(content: string, options?: RagIndexingOptions): Promise<Result<RagIndexingResult, RagError>> {
  13         try {
  14             const result = await indexDocument(content, options as any);
  15             const formattedResult = {
  16                 success: result.success,
  17                 chunksCreated: result.chunksCreated,
  18                 errors: result.errors
  19             };
  20 
  21             if (!result.success) {
  22                 return Result.fail(RagError.indexingFailed("Document indexing failed", result.errors));
  23             }
  24 
  25             return Result.ok(formattedResult);
  26         } catch (error: any) {
  27             return Result.fail(RagError.indexingFailed(error.message));
  28         }
