  29     });
  30 
  31     if (initialResults.length === 0) {
  32       return NextResponse.json({
  33         comparisons: [],
  34         message: 'No results found for comparison',
  35       });
  36     }
  37 
  38     // Determine which strategies to test
  39     const strategies: RerankStrategy[] = 
  40       strategy === 'all' 
  41         ? ['cross-encoder', 'bm25', 'hybrid']
  42         : [strategy as RerankStrategy];
  43 
  44     // Run comparison
  45     const reranker = getReranker();
  46     const comparisons = await Promise.all(
