  16           'What is machine learning?',
  17           'How to build web applications?',
  18           'Explain vector databases',
  19           'What is semantic search?',
  20           'Tell me about React',
  21         ];
  22 
  23         const scenarios = [
  24           { name: 'Without Cache', useCache: false, rerank: false },
  25           { name: 'With Cache', useCache: true, rerank: false },
  26           { name: 'With Cache + Re-ranking', useCache: true, rerank: true },
  27         ];
  28 
  29         const controllerInstance = container.resolve(RagController);
  30         const totalSteps = scenarios.length * testQueries.length;
  31         let currentStep = 0;
  32 
  33         for (const scenario of scenarios) {
  34           const times: number[] = [];
  35           let cacheHits = 0;
  36 
  37           // Run queries for this scenario
  38           for (const query of testQueries) {
  39             const startTime = Date.now();
  40             
  41             if (scenario.useCache) {
  42               const cacheHitResult = await controllerInstance.isSearchCacheHit(query, {});
  43               if (cacheHitResult.isSuccess && cacheHitResult.getValue()) {
  44                 cacheHits++;
  45               }
  46             }
  47 
  48             await controllerInstance.retrieveContext(query, {
  49               topK: 5,
  50               minScore: 0.5,
  51               useCache: scenario.useCache,
  52               rerank: scenario.rerank,
  53             });
  54 
  55             const time = Date.now() - startTime;
  56             times.push(time);
  57 
  58             currentStep++;
  59             const progress = Math.round((currentStep / totalSteps) * 100);
  60 
  61             // Send progress update
  62             controller.enqueue(
  63               encoder.encode(`data: ${JSON.stringify({ progress })}\n\n`)
  64             );
  65 
  66             // Small delay between queries
  67             await new Promise(resolve => setTimeout(resolve, 100));
  68           }
  69 
  70           // Calculate statistics
  71           const avgTime = times.reduce((a, b) => a + b, 0) / times.length;
  72           const minTime = Math.min(...times);
  73           const maxTime = Math.max(...times);
  74 
  75           const result = {
  76             scenario: scenario.name,
  77             avgTime,
  78             minTime,
  79             maxTime,
  80             cacheHits,
  81             totalQueries: testQueries.length,
  82           };
  83 
  84           // Send result
  85           controller.enqueue(
  86             encoder.encode(`data: ${JSON.stringify({ result })}\n\n`)
  87           );
  88         }
  89 
  90         controller.close();
  91       } catch (error) {
  92         console.error('Benchmark error:', error);
  93         controller.error(error);
  94       }
  95     },
  96   });
  97 
  98   return new Response(stream, {
  99     headers: {
 100       'Content-Type': 'text/event-stream',
 101       'Cache-Control': 'no-cache',
 102       'Connection': 'keep-alive',
 103     },
 104   });
