  42 
  43     if (!response.ok) {
  44       throw new Error(`Ollama API error: ${response.status} ${response.statusText}`);
  45     }
  46 
  47     const data = await response.json();
  48     const embedding = data.embedding;
  49     
  50     // Cache the result
  51     if (useCache) {
