  64 /**
  65  * Generate embeddings for multiple texts in batch
  66  */
  67 export async function generateEmbeddings(texts: string[]): Promise<number[][]> {
  68   try {
  69     // Process in parallel for better performance
  70     const embeddings = await Promise.all(
  71       texts.map(text => generateEmbedding(text))
  72     );
  73     return embeddings;
  74   } catch (error) {
  75     console.error('Error generating batch embeddings:', error);
  76     throw error;
  77   }
  78 }
  79 
  80 /**
  81  * Split text into chunks for embedding
  82  * This is important because embedding models have token limits
  83  */
  84 export function chunkText(
  85   text: string,
  86   options: {
  87     chunkSize?: number;
  88     overlap?: number;
  89     preserveParagraphs?: boolean;
  90   } = {}
  91 ): string[] {
  92   const {
  93     chunkSize = 500, // characters
  94     overlap = 50,
  95     preserveParagraphs = true,
  96   } = options;
  97 
  98   if (text.length <= chunkSize) {
  99     return [text];
 100   }
 101 
 102   const chunks: string[] = [];
 103 
 104   if (preserveParagraphs) {
 105     // Split by paragraphs first
 106     const paragraphs = text.split(/\n\n+/);
 107     let currentChunk = '';
 108 
 109     for (const paragraph of paragraphs) {
 110       if ((currentChunk + paragraph).length <= chunkSize) {
 111         currentChunk += (currentChunk ? '\n\n' : '') + paragraph;
 112       } else {
 113         if (currentChunk) {
 114           chunks.push(currentChunk);
 115         }
 116         
 117         // If single paragraph is larger than chunk size, split it
 118         if (paragraph.length > chunkSize) {
 119           const subChunks = splitLongText(paragraph, chunkSize, overlap);
 120           chunks.push(...subChunks);
 121           currentChunk = '';
 122         } else {
 123           currentChunk = paragraph;
 124         }
 125       }
 126     }
 127 
 128     if (currentChunk) {
 129       chunks.push(currentChunk);
 130     }
 131   } else {
 132     // Simple character-based chunking with overlap
 133     return splitLongText(text, chunkSize, overlap);
 134   }
 135 
 136   return chunks;
 137 }
 138 
 139 /**
 140  * Split long text into chunks with overlap
 141  */
 142 function splitLongText(text: string, chunkSize: number, overlap: number): string[] {
 143   const chunks: string[] = [];
 144   let start = 0;
 145 
 146   while (start < text.length) {
 147     const end = Math.min(start + chunkSize, text.length);
 148     chunks.push(text.slice(start, end));
 149     start = end - overlap;
 150     
 151     if (start >= text.length - overlap) break;
 152   }
 153 
 154   return chunks;
 155 }
 156 
 157 /**
 158  * Calculate the number of tokens (approximate)
 159  * This is a rough estimate: ~4 characters per token for English
 160  */
 161 export function estimateTokens(text: string): number {
 162   return Math.ceil(text.length / 4);
 163 }
