 140  * Combines semantic and keyword-based scoring
 141  */
 142 class HybridReranker {
 143   private bm25: BM25Scorer;
 144   private crossEncoder: CrossEncoderReranker;
 145 
 146   constructor() {
 147     this.bm25 = new BM25Scorer();
 148     this.crossEncoder = new CrossEncoderReranker();
 149   }
 150 
 151   /**
 152    * Re-rank using hybrid approach
 153    */
 154   async rerank(
 155     query: string,
 156     results: SearchResult[],
 157     options: RerankOptions = {}
 158   ): Promise<SearchResult[]> {
 159     const {
 160       topK = 10,
 161       weights = { semantic: 0.5, keyword: 0.3, recency: 0.2 },
 162     } = options;
 163 
 164     if (results.length === 0) return [];
 165 
 166     // Calculate average document length for BM25
 167     const avgLength = results.reduce((sum, r) => 
 168       sum + r.chunk.content.length, 0
 169     ) / results.length;
 170 
 171     // Score each result with multiple factors
 172     const scored = results.map(result => {
 173       // 1. Semantic score (original vector similarity)
 174       const semanticScore = result.score * (weights.semantic || 0.5);
 175 
 176       // 2. Keyword score (BM25)
 177       const bm25Score = this.bm25.score(query, result.chunk.content, avgLength);
 178       const normalizedBM25 = Math.min(1, bm25Score / 10); // Normalize
 179       const keywordScore = normalizedBM25 * (weights.keyword || 0.3);
 180 
 181       // 3. Recency score (if timestamp available)
 182       let recencyScore = 0;
 183       if (result.chunk.metadata.timestamp) {
 184         const ageMs = Date.now() - result.chunk.metadata.timestamp;
 185         const ageDays = ageMs / (1000 * 60 * 60 * 24);
 186         recencyScore = Math.exp(-ageDays / 30) * (weights.recency || 0.2); // Decay over 30 days
 187       }
 188 
 189       // Combined score
 190       const totalScore = semanticScore + keywordScore + recencyScore;
 191 
 192       return {
 193         ...result,
 194         score: totalScore,
 195         scoreBreakdown: {
 196           semantic: semanticScore,
 197           keyword: keywordScore,
 198           recency: recencyScore,
 199           total: totalScore,
 200         },
 201       };
 202     });
 203 
 204     // Sort and return top K
 205     return scored
 206       .sort((a, b) => b.score - a.score)
 207       .slice(0, topK);
 208   }
 209 }
