 215 class ReciprocalRankFusion {
 216   private k: number = 60; // RRF constant
 217 
 218   /**
 219    * Fuse multiple ranked lists using RRF
 220    */
 221   fuse(rankedLists: SearchResult[][], topK: number = 10): SearchResult[] {
 222     const scoreMap = new Map<string, { result: SearchResult; score: number }>();
 223 
 224     // Calculate RRF scores
 225     rankedLists.forEach(list => {
 226       list.forEach((result, rank) => {
 227         const id = result.chunk.id;
 228         const rrfScore = 1 / (this.k + rank + 1);
 229 
 230         if (scoreMap.has(id)) {
 231           scoreMap.get(id)!.score += rrfScore;
 232         } else {
 233           scoreMap.set(id, { result, score: rrfScore });
 234         }
 235       });
 236     });
 237 
 238     // Sort by RRF score and take top K
 239     return Array.from(scoreMap.values())
 240       .sort((a, b) => b.score - a.score)
 241       .slice(0, topK)
 242       .map(item => ({
 243         ...item.result,
 244         score: item.score,
 245       }));
 246   }
 247 }
