 270   ): Promise<SearchResult[]> {
 271     const { strategy = 'hybrid', topK = 10 } = options;
 272 
 273     if (results.length === 0) return [];
 274 
 275     switch (strategy) {
 276       case 'cross-encoder':
 277         return this.crossEncoder.rerank(query, results, topK);
 278 
 279       case 'bm25':
 280         // BM25 only (part of hybrid)
 281         return this.hybrid.rerank(query, results, {
 282           ...options,
 283           weights: { semantic: 0, keyword: 1, recency: 0 },
 284         });
 285 
 286       case 'hybrid':
 287         return this.hybrid.rerank(query, results, options);
 288 
 289       case 'reciprocal-rank-fusion':
 290         // For RRF, we'd need multiple ranked lists
 291         // Here we just return sorted results
 292         return results
 293           .sort((a, b) => b.score - a.score)
 294           .slice(0, topK);
 295 
 296       default:
 297         return results.slice(0, topK);
 298     }
 299   }
