  96                         checks.vectorStore.details = { error: 'Health check failed' };
  97                     }
  98                 } else {
  99                     const size = typeof vectorStore.size === 'function'
 100                         ? await vectorStore.size()
 101                         : vectorStore.size();
 102 
 103                     checks.vectorStore.status = 'ok';
 104                     checks.vectorStore.details = {
 105                         type: 'memory',
 106                         totalChunks: size,
 107                     };
 108                 }
 109             } catch (error: unknown) {
 110                 checks.vectorStore.status = 'error';
 111                 checks.vectorStore.details = {
 112                     error: error instanceof Error ? error.message : 'Unknown error',
 113                 };
 114             }
 115 
 116             try {
 117                 const response = await fetch(`${RAGConfig.ollama.baseUrl}/api/tags`, {
 118                     method: 'GET',
 119                     signal: AbortSignal.timeout(5000),
 120                 });
 121 
 122                 if (response.ok) {
 123                     const data = await response.json() as { models?: Array<{ name: string }> };
 124                     const hasEmbeddingModel = data.models?.some(
 125                         (model) => model.name.includes(RAGConfig.ollama.embeddingModel)
 126                     ) ?? false;
 127 
 128                     checks.ollama.status = hasEmbeddingModel ? 'ok' : 'error';
 129                     checks.ollama.details = {
 130                         url: RAGConfig.ollama.baseUrl,
 131                         model: RAGConfig.ollama.embeddingModel,
 132                         modelAvailable: hasEmbeddingModel,
 133                         availableModels: data.models?.map((model) => model.name).slice(0, 5) ?? [],
 134                     };
 135                 } else {
 136                     checks.ollama.status = 'error';
 137                     checks.ollama.details = {
 138                         error: `HTTP ${response.status}: ${response.statusText}`,
 139                     };
 140                 }
 141             } catch (error: unknown) {
 142                 checks.ollama.status = 'error';
 143                 checks.ollama.details = {
 144                     error: error instanceof Error ? error.message : 'Connection failed',
 145                     url: RAGConfig.ollama.baseUrl,
 146                 };
 147             }
 148 
 149             const allOk = Object.values(checks).every((check) => check.status === 'ok');
 150             return Result.ok({
 151                 status: allOk ? 'healthy' : 'degraded',
 152                 timestamp: new Date().toISOString(),
 153                 checks,
 154                 config: {
 155                     provider: RAGConfig.vectorStore.provider,
 156                     embeddingModel: RAGConfig.ollama.embeddingModel,
 157                     vectorDimension: RAGConfig.vectorStore.dimension,
 158                 },
 159             });
 160         } catch (error: any) {
 161             return Result.fail(RagError.internal(error.message));
 162         }
 163     }
 164 
 165     async compareReranking(query: string, strategy: RagRerankStrategy | 'all' = 'all'): Promise<Result<RagRerankComparisonResult, RagError>> {
 166         try {
 167             const queryEmbedding = await generateEmbedding(query);
 168             const vectorStore = getVectorStore();
 169             const initialResults = await vectorStore.search(queryEmbedding, {
 170                 topK: 10,
 171                 minScore: 0.3,
 172             });
 173 
 174             if (initialResults.length === 0) {
 175                 return Result.ok({ comparisons: [], initialResultCount: 0 });
 176             }
 177 
 178             const reranker = getReranker();
 179 
 180             if (strategy !== 'all') {
 181                 const startTime = Date.now();
 182                 const rerankedResults = await reranker.rerank(query, initialResults, {
 183                     strategy: strategy as RerankStrategy,
 184                     topK: 5,
 185                 });
 186                 const elapsed = Date.now() - startTime;
 187                 const avgScore = rerankedResults.length > 0
 188                     ? rerankedResults.reduce((sum, item) => sum + item.score, 0) / rerankedResults.length
 189                     : 0;
 190 
 191                 return Result.ok({
 192                     comparisons: [{
 193                         strategy,
 194                         results: rerankedResults.map((item) => ({
 195                             content: item.chunk.content,
 196                             score: item.score,
 197                             sourceFile: item.chunk.metadata.sourceFile,
 198                         })),
 199                         avgScore,
 200                         time: elapsed,
 201                     }],
 202                     initialResultCount: initialResults.length,
 203                 });
 204             }
 205 
 206             const benchmarkComparisons = await reranker.benchmark(query, initialResults, 5);
 207             const formattedComparisons = benchmarkComparisons.map((comparison) => ({
 208                 strategy: comparison.strategy,
 209                 results: comparison.results.map((item) => ({
 210                     content: item.chunk.content,
 211                     score: item.score,
 212                     sourceFile: item.chunk.metadata.sourceFile,
 213                 })),
 214                 avgScore: comparison.avgScore,
 215                 time: comparison.time,
 216             }));
 217 
 218             return Result.ok({
 219                 comparisons: formattedComparisons,
 220                 initialResultCount: initialResults.length,
 221             });
 222         } catch (error: any) {
 223             return Result.fail(RagError.retrievalFailed(error.message));
 224         }
 225     }
 226 
 227     async getCacheStats(): Promise<Result<RagCacheStats, RagError>> {
 228         try {
 229             const cacheManager = getCacheManager();
 230             return Result.ok(cacheManager.getAllStats());
 231         } catch (error: any) {
 232             return Result.fail(RagError.internal(error.message));
 233         }
 234     }
