 236     async isSearchCacheHit(query: string, options?: RagSearchCacheLookupOptions): Promise<Result<boolean, RagError>> {
 237         try {
 238             const cacheManager = getCacheManager();
 239             const cache = cacheManager.getSearchCache();
 240             return Result.ok(cache.getResults(query, options ?? {}) !== null);
 241         } catch (error: any) {
 242             return Result.fail(RagError.internal(error.message));
 243         }
 244     }
