 246     async clearCache(): Promise<Result<void, RagError>> {
 247         try {
 248             const cacheManager = getCacheManager();
 249             cacheManager.clearAll();
 250             return Result.ok();
 251         } catch (error: any) {
 252             return Result.fail(RagError.internal(error.message));
 253         }
 254     }
 255 
 256     async clear(): Promise<Result<void, RagError>> {
 257         try {
 258             const vectorStore = getVectorStore();
 259             await vectorStore.clear();
 260             return Result.ok();
 261         } catch (error: any) {
 262             return Result.fail(RagError.vectorStoreError(error.message));
 263         }
 264     }
